"""Contract checks; the expected extraction is authored, not generated by AI inference."""

from copy import deepcopy
import json
from pathlib import Path
import unittest

from jobhunter.requirements import validate_requirements


FIXTURES = Path(__file__).parent / "fixtures"


class RequirementTests(unittest.TestCase):
    def setUp(self):
        self.source = (FIXTURES / "job_001.txt").read_text(encoding="utf-8")
        self.payload = json.loads((FIXTURES / "job_001.expected.json").read_text(encoding="utf-8"))

    def test_golden_example_has_expected_priorities_and_evidence(self):
        result = validate_requirements(self.payload, self.source)
        self.assertEqual([r.priority for r in result], ["mandatory", "mandatory", "optional", "unknown"])
        self.assertEqual(len(result), 4)
        self.assertEqual(result[0].quote, "At least 3 years of engineering team leadership.")

    def test_invented_or_changed_evidence_is_rejected(self):
        self.payload["requirements"][0]["quote"] = "German fluency is required."
        with self.assertRaisesRegex(ValueError, "exactly match"):
            validate_requirements(self.payload, self.source)

    def test_invalid_offsets_are_rejected(self):
        for start, end in [(True, 152), (-1, 152), (105, 9999), (152, 105), ("105", 152), (106, 152)]:
            with self.subTest(start=start, end=end):
                payload = deepcopy(self.payload)
                payload["requirements"][0].update(start=start, end=end)
                with self.assertRaises(ValueError):
                    validate_requirements(payload, self.source)

    def test_duplicate_ids_and_invalid_priorities_are_rejected(self):
        for changes in [{"id": "R2"}, {"priority": "preferred"}, {"priority": []}, {"quote": " "}]:
            with self.subTest(changes=changes):
                payload = deepcopy(self.payload)
                payload["requirements"][0].update(changes)
                with self.assertRaises(ValueError):
                    validate_requirements(payload, self.source)

    def test_missing_or_extra_fields_are_rejected(self):
        for field in ["quote", "priority", "start"]:
            payload = deepcopy(self.payload)
            del payload["requirements"][0][field]
            with self.subTest(missing=field), self.assertRaises(ValueError):
                validate_requirements(payload, self.source)
        self.payload["requirements"][0]["score"] = 100
        with self.assertRaises(ValueError):
            validate_requirements(self.payload, self.source)

    def test_invalid_envelopes_are_rejected(self):
        for payload in [None, [], {}, {"schema_version": "2", "requirements": []}, {"schema_version": "1", "requirements": {}}]:
            with self.subTest(payload=payload), self.assertRaises(ValueError):
                validate_requirements(payload, self.source)

    def test_unicode_offsets_and_no_requirements(self):
        source = "Locație: România.\nCerință: comunicare în română."
        quote = "comunicare în română"
        start = source.index(quote)
        payload = {"schema_version": "1", "requirements": [
            {"id": "R1", "priority": "unknown", "quote": quote, "start": start, "end": start + len(quote)}
        ]}
        self.assertEqual(validate_requirements(payload, source)[0].quote, quote)
        self.assertEqual(validate_requirements({"schema_version": "1", "requirements": []}, source), ())
        with self.assertRaises(ValueError):
            validate_requirements(payload, " ")
